void PVXLog(NSString *format, ...) { va_list args; va_start(args,format); NSString *s=[[NSString alloc] initWithFormat:format arguments:args]; va_end(args); NSLog(@"[PyVideoPlus] %@",s); }
id PVXGet(id obj, NSString *key) { if(!obj)return nil; @try{return [obj valueForKey:key];} @catch(NSException *e){return nil;} }
BOOL PVXHook(Class cls, SEL sel, IMP repl, IMP *original) {
 if(!cls||!sel||!repl)return NO; Method m=class_getInstanceMethod(cls,sel); if(!m)return NO;
 typedef void(*HookFn)(Class,SEL,IMP,IMP*); HookFn hook=(HookFn)dlsym(RTLD_DEFAULT,"MSHookMessageEx");
 if(!hook){void *h=dlopen("/usr/lib/libsubstrate.dylib",RTLD_NOW); if(h)hook=(HookFn)dlsym(h,"MSHookMessageEx");}
 if(hook){hook(cls,sel,repl,original);return YES;}
 IMP old=method_getImplementation(m); if(original)*original=old;
 if(!class_addMethod(cls,sel,repl,method_getTypeEncoding(m))) method_setImplementation(class_getInstanceMethod(cls,sel),repl);
 return YES;
}
id PVXBrowser(void) { Class c=NSClassFromString(@"PVBrowser"); SEL s=NSSelectorFromString(@"shared"); return [c respondsToSelector:s]?((id(*)(id,SEL))objc_msgSend)(c,s):nil; }
WKWebView *PVXCurrentWebView(void){id b=PVXBrowser();SEL s=NSSelectorFromString(@"currentWebView");id w=[b respondsToSelector:s]?((id(*)(id,SEL))objc_msgSend)(b,s):nil;return [w isKindOfClass:WKWebView.class]?w:nil;}
NSString *PVXStateRoot(void){ typedef id(*RootFn)(void);RootFn fn=(RootFn)dlsym(RTLD_DEFAULT,"PVStateDirectory");if(fn){id p=fn();if([p isKindOfClass:NSString.class]&&[p length])return p;} typedef id(*JB)(id);JB jb=(JB)dlsym(RTLD_DEFAULT,"_Z6jbrootP8NSString");NSString *p=@"/var/mobile/Library/Application Support/com.crctdd.pyvideo";return jb?(jb(p)?:@""):p; }
NSString *PVXResourcePath(NSString *name){typedef id(*Root)(id);Root f=(Root)dlsym(RTLD_DEFAULT,"PVRoot");NSString *p=[@"/Library/Application Support/PyVideoPlus" stringByAppendingPathComponent:name];return f?(f(p)?:p):p;}
static UIViewController *PVXTop(UIViewController *c){while(c){if(c.presentedViewController&&!c.presentedViewController.isBeingDismissed){c=c.presentedViewController;continue;}if([c isKindOfClass:UINavigationController.class]){c=((UINavigationController*)c).visibleViewController;continue;}if([c isKindOfClass:UITabBarController.class]){c=((UITabBarController*)c).selectedViewController;continue;}break;}return c;}
UIViewController *PVXPresenter(void){UIWindow *best=nil;for(UIScene *scene in UIApplication.sharedApplication.connectedScenes){if(![scene isKindOfClass:UIWindowScene.class]||scene.activationState!=UISceneActivationStateForegroundActive)continue;for(UIWindow *w in ((UIWindowScene*)scene).windows){if(w.hidden||w.alpha<0.01||!w.rootViewController)continue;if(!best||w.windowLevel>best.windowLevel||w.isKeyWindow)best=w;}}return PVXTop(best.rootViewController);}
void PVXAlert(NSString *title,NSString *message){dispatch_async(dispatch_get_main_queue(),^{UIViewController *p=PVXPresenter();if(!p)return;UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];[p presentViewController:a animated:YES completion:nil];});}
void PVXOpenDownloads(void){dispatch_async(dispatch_get_main_queue(),^{id b=PVXBrowser();SEL s=NSSelectorFromString(@"show");if([b respondsToSelector:s])((void(*)(id,SEL))objc_msgSend)(b,s);else PVXAlert(@"PyVideo",@"原插件尚未加载，请确认已启用 PyVideo 并重新打开 Safari。");});}
static NSURL *PVXHTTP(id v){NSURL *u=[v isKindOfClass:NSURL.class]?v:([v isKindOfClass:NSString.class]?[NSURL URLWithString:v]:nil);return ([u.scheme.lowercaseString isEqual:@"https"]||[u.scheme.lowercaseString isEqual:@"http"])&&u.host.length?u:nil;}
static NSURL *PVXPlayerURL(id context){NSMutableArray *q=[NSMutableArray array];if(context)[q addObject:context];NSHashTable *seen=[NSHashTable hashTableWithOptions:NSPointerFunctionsObjectPointerPersonality];for(NSUInteger n=0;n<q.count&&n<40;n++){id o=q[n];if([seen containsObject:o])continue;[seen addObject:o];NSURL *u=PVXHTTP(o);if(u)return u;if([o isKindOfClass:AVURLAsset.class])return PVXHTTP([(AVURLAsset*)o URL]);if([o isKindOfClass:NSDictionary.class]){for(NSString *k in @[@"url",@"URL",@"sourceURL",@"asset",@"player",@"currentItem",@"playerController",@"playerViewController"]){id x=o[k];if(x&&x!=NSNull.null)[q addObject:x];}continue;}for(NSString *k in @[@"player",@"currentItem",@"asset",@"playerController",@"playerViewController",@"contentURL"]){id x=PVXGet(o,k);if(x&&x!=o)[q addObject:x];}}return nil;}
static void PVXSubmitPlaying(NSURL *u,NSDictionary *active){WKWebView *w=PVXCurrentWebView();id b=PVXBrowser();SEL sel=NSSelectorFromString(@"download:completion:");if(!w||![b respondsToSelector:sel]){PVXAlert(@"无法下载当前视频",@"当前 Safari 网页已经关闭或原插件尚未就绪。");return;}NSArray *list=PVXGet(b,@"candidates");NSDictionary *chosen=nil;for(id item in list){if(![item isKindOfClass:NSDictionary.class])continue;for(id source in item[@"sources"]){if([source isKindOfClass:NSDictionary.class]&&[source[@"url"] isEqual:u.absoluteString]){chosen=item;break;}}if(chosen)break;}
 if(!chosen){NSMutableDictionary *c=[@{@"key":NSUUID.UUID.UUIDString,@"title":w.title?:@"当前播放视频",@"page":w.URL.absoluteString?:@"",@"sources":@[@{@"url":u.absoluteString,@"height":@0,@"type":@""}],@"poster":@"",@"blob":@NO} mutableCopy];if([active[@"frame"] isKindOfClass:NSString.class])c[@"frame"]=active[@"frame"];chosen=c;}
 ((void(*)(id,SEL,id,id))objc_msgSend)(b,sel,chosen,^(NSString *error){if(error.length)PVXAlert(@"视频下载未提交",error);else PVXAlert(@"已加入视频下载",@"后台将下载当前影片并保存到相册。可在 PyVideo 浮窗查看进度。");});}
void PVXDownloadPlayingVideo(id context){dispatch_async(dispatch_get_main_queue(),^{NSURL *u=PVXPlayerURL(context);NSDictionary *active=PVXActiveVideo();if(u){PVXSubmitPlaying(u,active?:@{});return;}u=PVXHTTP(active[@"url"]);if(u){PVXSubmitPlaying(u,active);return;}PVXAlert(@"尚未取得当前影片直链",@"播放器目前仅提供 blob 或未提供可下载来源。请返回网页播放一次后重试；不会改为下载页面中其他影片。");});}
__attribute__((constructor)) static void PVXInit(void){@autoreleasepool{if(![NSBundle.mainBundle.bundleIdentifier isEqual:@"com.apple.mobilesafari"])return;dispatch_async(dispatch_get_main_queue(),^{PVXInstallMenuHooks();PVXInstallPlayerHooks();PVXInstallImages();PVXLog(@"enhancement loaded version 0.1.0");});}}
